        return _student_t_density(dist, xloc, parameters, cache)
    elif dist.name == 'Cauchy':
        return _cauchy_density(dist, xloc, parameters, cache)
    elif dist.name == 'Laplace':
        return _laplace_density(dist, xloc, parameters, cache)
    elif dist.name == 'Logistic':
        return _logistic_density(dist, xloc, parameters, cache)
    elif dist.name == 'LogNormal':
        return _lognormal_density(dist, xloc, parameters, cache)
    elif dist.name == 'Exponential':
        return _exponential_density(dist, xloc, parameters, cache)
    elif dist.name == 'Binomial':
        return _binomial_density(dist, xloc, parameters, cache)
    elif dist.name == 'NegativeBinomial':
        return _negative_binomial_density(dist, xloc, parameters, cache)
    elif dist.name == 'Geometric':
        return _geometric_density(dist, xloc, parameters, cache)
    elif dist.name == 'Poisson':
